import test from'node:test';import assert from'node:assert/strict';import{createHash}from'node:crypto';import{execFileSync}from'node:child_process';import{persistProtectedJobEvidence}from'./protected-job-evidence.mjs';
const sha=(x,a='sha256')=>createHash(a).update(x).digest('hex');
// Test keys are generated by the test command, never user key material.
const key=process.env.ZZ_TEST_AGE_KEY,recipient=key?execFileSync('age-keygen',['-y',key],{encoding:'utf8'}).trim():null;
test('real age encryption -> bounded private Git write -> exact remote readback -> decrypt',{skip:!key},async t=>{
 const p={repository_id:'999001',owner:'ZZ-owner',repo:'ZZ-private',branch:'ZZ-main',parent_commit:'a'.repeat(40),path:'ZZ-prewrite.age',recipient:sha(recipient),operation_binding:'b'.repeat(64),run_id:'999002',stage:'pre_write',existing_total_bytes:0};
 const c={mode:'unreleased_protected_job_evidence',production_enabled:false,recipient,storage:p},raw=JSON.stringify(c),env={FATHER_EVIDENCE_RELEASE_JSON:raw,FATHER_EVIDENCE_RELEASE_SHA256:sha(raw),PRIVATE_GIT_CREDENTIAL:'ZZsynthetic',GITHUB_RUN_ATTEMPT:'1',GITHUB_REF:'refs/heads/master',GITHUB_EVENT_NAME:'workflow_dispatch',GITHUB_RUN_ID:p.run_id};
 const plaintext=Buffer.from(JSON.stringify({name:'ZZFather',public:false}));let bytes,blob,entry,n=0;const root='https://api.github.com/repos/ZZ-owner/ZZ-private',tree='c'.repeat(40),commit='d'.repeat(40),old='e'.repeat(40);const ref=x=>({ref:'refs/heads/ZZ-main',object:{type:'commit',sha:x}}),co={sha:commit,tree:{sha:tree},parents:[{sha:p.parent_commit}]};const events=[];
 t.mock.method(globalThis,'fetch',async(url,o)=>{n++;assert.equal(o.headers.Authorization,'Bearer ZZsynthetic');assert.equal(o.redirect,'manual');let body;if(o.method==='POST'&&url===root+'/git/blobs'){bytes=Buffer.from(JSON.parse(o.body).content,'base64');assert.ok(!bytes.includes(plaintext));blob=sha(Buffer.concat([Buffer.from('blob '+bytes.length+'\0'),bytes]),'sha1');entry={path:p.path,mode:'100644',type:'blob',sha:blob};body={sha:blob};}
 else if(url==='https://api.github.com/repositories/999001')body={id:999001,private:true,full_name:'ZZ-owner/ZZ-private'};
 else if(url===root+'/git/ref/heads/ZZ-main')body=ref(n===2?p.parent_commit:commit);
 else if(url===root+'/git/commits/'+p.parent_commit)body={sha:p.parent_commit,tree:{sha:old}};
 else if(url===root+'/git/trees/'+old)body={sha:old,truncated:false,tree:[]};
 else if(url===root+'/git/trees'&&o.method==='POST')body={sha:tree,truncated:false,tree:[entry]};
 else if(url===root+'/git/commits'||url===root+'/git/commits/'+commit)body=co;
 else if(url===root+'/git/refs/heads/ZZ-main'){assert.equal(JSON.parse(o.body).force,false);body=ref(commit);}
 else if(url===root+'/git/blobs/'+blob)body={sha:blob,encoding:'base64',size:bytes.length,content:bytes.toString('base64')};
 else throw Error('unexpected route');return Response.json(body,{status:o.method==='POST'?201:200});});
 const result=await persistProtectedJobEvidence(env,plaintext,x=>events.push(x));assert.equal(n,11);assert.equal(result.descriptor.commit,commit);assert.equal(result.post_permitted,false);assert.equal(events.length,4);assert.deepEqual(execFileSync('age',['-d','-i',key],{input:bytes}),plaintext);
});
test('wrong config hash stops before age or HTTP',async()=>{await assert.rejects(persistProtectedJobEvidence({FATHER_EVIDENCE_RELEASE_JSON:'{}',FATHER_EVIDENCE_RELEASE_SHA256:'0'.repeat(64)},new Uint8Array([1]),()=>{}));});
